function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // bird
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50 + Math.cos(t)*30, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50 - Math.cos(t)*30, H/2 + 50);
  ctx.stroke();

  // fish
  ctx.beginPath();
  ctx.arc(W/2 + 100 + Math.sin(t)*20, H/2 + 100, 15, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + Math.sin(t)*20, H/2 + 115);
  ctx.lineTo(W/2 + 100 + Math.sin(t)*20 + Math.cos(t)*20, H/2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + Math.sin(t)*20, H/2 + 115);
  ctx.lineTo(W/2 + 100 + Math.sin(t)*20 - Math.cos(t)*20, H/2 + 130);
  ctx.stroke();

  // rabbit
  ctx.beginPath();
  ctx.arc(W/2 - 100 + Math.sin(t)*10, H/2 + 50, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + Math.sin(t)*10, H/2 + 70);
  ctx.lineTo(W/2 - 100 + Math.sin(t)*10 + Math.cos(t)*15, H/2 + 85);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + Math.sin(t)*10, H/2 + 70);
  ctx.lineTo(W/2 - 100 + Math.sin(t)*10 - Math.cos(t)*15, H/2 + 85);
  ctx.stroke();

  ctx.restore();
}
